import { DOCUMENT_KINDS, expect, expectStatus, test } from "../../fixtures";

test("Approving every extraction approves the vendor", { tag: "@REV-05" }, async ({ apiAs, factory }) => {
  // Arrange
  const reviewer = await apiAs("reviewer");
  const { vendor, extractions } = await factory.vendorInReview();

  // Act
  for (const kind of DOCUMENT_KINDS) {
    const response = await reviewer.post(`/api/extractions/${extractions[kind].id}/decision`, {
      data: { decision: "approve" },
    });
    await expectStatus(response, 200);
  }

  // Assert
  // Approval is recorded in the background, so poll the stored vendor rather than assume it is immediate.
  await expect
    .poll(
      async () => (await expectStatus<{ status: string }>(await reviewer.get(`/api/vendors/${vendor.id}`), 200)).status,
      { message: "vendor status after approving all extractions", timeout: 15_000 },
    )
    .toBe("approved");

  await expect
    .poll(
      async () => {
        const trail = await expectStatus<{ items: { action: string }[] }>(
          await reviewer.get(`/api/vendors/${vendor.id}/audit`),
          200,
        );
        return trail.items.map((event) => event.action);
      },
      { message: "audit trail after approving all extractions", timeout: 15_000 },
    )
    .toContain("vendor.approved");
});
